const lessons=[{"sentences":[{"speaker":"A","text":"Hello Mark, because our main printer is broken, we need to reschedule the client meeting this morning.","position":1,"audioStartSeconds":0,"audioEndSeconds":6.435416666666667},{"speaker":"B","text":"That is unfortunate since the customer is travelling from another city today.","position":2,"audioStartSeconds":6.635416666666667,"audioEndSeconds":11.60175},{"speaker":"A","text":"Can we move their appointment to Thursday afternoon instead of today?","position":3,"audioStartSeconds":11.80175,"audioEndSeconds":15.848916666666666},{"speaker":"B","text":"Let me check the calendar before I promise anything.","position":4,"audioStartSeconds":16.048916666666667,"audioEndSeconds":19.683708333333332},{"speaker":"A","text":"Please hurry because they are arriving in our office lobby soon.","position":5,"audioStartSeconds":19.883708333333335,"audioEndSeconds":23.788333333333334},{"speaker":"B","text":"Thursday at two pm is completely free so I will email them right now.","position":6,"audioStartSeconds":23.988333333333333,"audioEndSeconds":28.563083333333335},{"speaker":"A","text":"Thank you for fixing that problem so quickly.","position":7,"audioStartSeconds":28.763083333333334,"audioEndSeconds":32.139375},{"speaker":"A","text":"Excuse me Sarah, do you have the financial reports ready for the board meeting tomorrow?","role":"section-start","position":8,"audioStartSeconds":37.139375,"audioEndSeconds":42.33266666666667},{"speaker":"B","text":"I finished drafting them yesterday but I still need your signature on the final page.","position":9,"audioStartSeconds":42.532666666666664,"audioEndSeconds":47.674416666666666},{"speaker":"A","text":"I can sign them right now if you bring the papers to my desk.","position":10,"audioStartSeconds":47.87441666666667,"audioEndSeconds":52.011041666666664},{"speaker":"B","text":"Actually I left the folder upstairs on my office table.","position":11,"audioStartSeconds":52.21104166666667,"audioEndSeconds":56.283208333333334},{"speaker":"A","text":"Please go upstairs and fetch them while I finish this phone call.","position":12,"audioStartSeconds":56.48320833333333,"audioEndSeconds":60.65479166666667},{"speaker":"B","text":"I will be back in two minutes with the complete document package.","position":13,"audioStartSeconds":60.854791666666664,"audioEndSeconds":65.09441666666666}],"questions":[{"prompt":"Why does Speaker A want to reschedule the meeting?","options":["The client is travelling.","The main printer is broken.","The calendar is full."],"answer":"B","evidenceSentence":1,"evidence":"because our main printer is broken","explanation":"Speaker A cho biết máy in chính bị hỏng nên phải dời lịch cuộc họp."},{"prompt":"When is the new appointment scheduled?","options":["Thursday afternoon.","Friday morning.","Today at two pm."],"answer":"A","evidenceSentence":3,"evidence":"Thursday afternoon","explanation":"Họ thống nhất dời cuộc họp sang chiều thứ Năm."},{"prompt":"What does Speaker B need to do next?","options":["Fix the printer.","Meet the client.","Email the customer."],"answer":"C","evidenceSentence":6,"evidence":"I will email them right now","explanation":"Speaker B sẽ gửi email cho khách hàng ngay lập tức."},{"prompt":"What documents are discussed in the second conversation?","options":["Financial reports.","Travel itineraries.","Printer manuals."],"answer":"A","evidenceSentence":8,"evidence":"financial reports","explanation":"Hai người bàn về các báo cáo tài chính cho cuộc họp hội đồng quản trị."},{"prompt":"Where are the documents currently located?","options":["On Speaker A's desk.","Upstairs on a table.","In the lobby."],"answer":"B","evidenceSentence":11,"evidence":"upstairs on my office table","explanation":"Tài liệu đang ở trên bàn làm việc trên tầng lầu."},{"prompt":"What will Speaker B do right after the conversation?","options":["Answer a phone call.","Sign the papers.","Fetch the folder."],"answer":"C","evidenceSentence":12,"evidence":"fetch them","explanation":"Speaker B sẽ đi lấy tập tài liệu về."}]}];const cards=[...document.querySelectorAll('article')];let stopping=null,stoppingAudio=null;
    document.addEventListener('play',event=>{if(event.target.tagName!=='AUDIO')return;document.querySelectorAll('audio').forEach(a=>{if(a!==event.target)a.pause()})},true);
    document.querySelectorAll('[data-filter]').forEach(button=>button.onclick=()=>{let count=0;cards.forEach(c=>{c.hidden=button.dataset.filter!=='ALL'&&c.dataset.goal!==button.dataset.filter;if(!c.hidden)count++;else c.querySelector('audio').pause()});document.querySelectorAll('[data-filter]').forEach(b=>b.setAttribute('aria-pressed',b===button));document.querySelector('#filter-status').textContent='Đang hiển thị '+count+' bài.'});
    const normal=value=>value.trim().toLowerCase().replace(/\s+/g,' ');
    document.querySelectorAll('[data-check]').forEach(button=>button.onclick=()=>{const i=Number(button.dataset.check);let score=0;lessons[i].questions.forEach((q,n)=>{const value=normal(document.getElementById('answer-'+i+'-'+n).value);if([q.answer,...(q.accepted||[])].some(a=>normal(a)===value))score++});document.getElementById('result-'+i).textContent=score+'/'+lessons[i].questions.length+' câu đúng. Mở phần đáp án để xem giải thích.'});
    document.querySelectorAll('[data-segment]').forEach(button=>button.onclick=async()=>{if(stopping)stopping();const [i,n]=button.dataset.segment.split(',').map(Number),audio=cards[i].querySelector('audio'),s=lessons[i].sentences[n];audio.currentTime=s.audioStartSeconds;const stop=()=>{stopping=null;stoppingAudio=null;audio.removeEventListener('timeupdate',check);audio.pause()},check=()=>{if(audio.currentTime>=s.audioEndSeconds)stop()};stopping=stop;stoppingAudio=audio;audio.addEventListener('timeupdate',check);try{await audio.play()}catch(_){stop();document.getElementById('result-'+i).textContent='Không phát được audio. Hãy dùng nút tải WAV để nghe.'}});
    document.querySelectorAll('audio').forEach(audio=>audio.addEventListener('pause',()=>{if(audio.paused&&stoppingAudio===audio&&stopping)stopping()}));
const authStatus=document.querySelector('#auth-status');
async function initializeAudio(){
 try{
  const response=await fetch('/api/auth/me',{credentials:'same-origin'});
  if(response.status===401){authStatus.hidden=false;authStatus.innerHTML='Đăng nhập để nghe audio. <a href="/login?next=%2Fcatalog%3Fgoal%3DALL">Đăng nhập</a> rồi mở bài từ thư viện bằng nút “Nghe toàn bài & làm câu hỏi”.';return}
  if(!response.ok)throw Error('account');
  document.querySelectorAll('audio').forEach(audio=>{audio.src=audio.dataset.src;audio.preload='none';audio.hidden=false});
  document.querySelectorAll('[data-segment]').forEach(button=>button.disabled=false);
  document.querySelectorAll('a[download]').forEach(link=>link.hidden=false);
 }catch(_){authStatus.hidden=false;authStatus.textContent='Không kiểm tra được đăng nhập. Hãy tải lại trang để thử lại.'}
}
initializeAudio();
